const icons={display:'<circle cx="12" cy="12" r="8.5"/><path d="M12 3.5v17"/><path d="M12 3.5a8.5 8.5 0 0 1 0 17z" fill="currentColor" stroke="none"/>',fullscreen:'<path d="M4 9V4h5M15 4h5v5M20 15v5h-5M9 20H4v-5"/>',pause:'<path d="M9 5v14M15 5v14"/>',play:'<path d="M8 5l11 7-11 7z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',compare:'<path d="M8 3v18M16 3v18M3 7h10M11 17h10"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',reset:'<path d="M4 5v6h6M4 11a8 8 0 1 1 2 7"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',share:'<path d="M12 16V3m-5 5 5-5 5 5M5 12v9h14v-9"/>',check:'<path d="m5 12 4 4L19 6"/>',left:'<path d="m15 5-7 7 7 7"/>',right:'<path d="m9 5 7 7-7 7"/>'};
