const app=$('#app');let globe=null;let saved=[];let persist=true;let lastTitle='';let toastTimer;let atlasFilter={q:'',family:'All materials',sort:'featured'};
try{const value=JSON.parse(localStorage.getItem('fibersOfEarth.saved.v2')||'[]');saved=Array.isArray(value)?value.filter(id=>byId[id]):[];}catch{persist=false;}
