const SITE='https://sharpmeow.github.io/FibersOfEarth/';
const EDITION='2.2';
// Prose with the first mention of each glossary term linked once per page.
function prose(text,used){return text?`<p>${linkTerms(emphasize(esc(text)),undefined,used)}</p>`:'';}
function detailBlock(m,key,heading,used){return m.detail?.[key]?`<h3>${heading}</h3>${prose(m.detail[key],used)}`:'';}
function citation(m){const url=SITE+'#/fiber/'+m.id,today=new Date().toISOString().slice(0,10);return {apa:`Chaos. (2026). ${m.name}. In Fibers of Earth: An independent textile atlas (Edition ${EDITION}). Retrieved ${today}, from ${url}`,bibtex:`@misc{fibersofearth-${m.id},\n  author = {Chaos},\n  title = {${m.name.replace(/[{}]/g,'')}},\n  howpublished = {Fibers of Earth: An independent textile atlas, edition ${EDITION}},\n  year = {2026},\n  url = {${url}},\n  note = {Accessed ${today}}\n}`};}
function evidenceBox(m){const d=m.detail;if(!d)return '';return `${d.facts?.length?`<section class="fact-box key-figures"><h3>Key figures</h3>${d.facts.map(([k,v])=>`<div class="fact-row"><small>${esc(k)}</small>${esc(v)}</div>`).join('')}<small class="muted">Approximate values under the stated conditions. Real products vary with grade, construction and finishing.</small></section>`:''}${d.refs?.length?`<section class="fact-box"><h3>Research references</h3><ul class="source-links">${d.refs.map(r=>`<li><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a></li>`).join('')}</ul><small class="muted">${d.evidence==='editorial'?'Editorial summary of established textbook knowledge; the references are starting points rather than line-by-line verification.':'Specific figures, dates and legal points in this profile were checked against these references.'}</small></section>`:''}`;}
function citeBox(m){const c=citation(m);return `<section class="fact-box cite-box"><h3>Cite this profile</h3><p class="cite-text">${esc(c.apa)}</p><div class="actions"><button class="button small" data-cite="apa" data-id="${m.id}">Copy APA</button><button class="button small" data-cite="bibtex" data-id="${m.id}">Copy BibTeX</button></div></section>`;}
function profile(id,tab='overview'){const m=byId[id];if(!m)return notFound();title(m.name);const js=journeys.filter(j=>j.fiber===id);const sci=scienceFor(m.brand?byId[m.base]:m);const g=m.guide;const tabs=[['overview','Overview'],['types','Types & fabrics'],['care','Buying & care'],['history','History'],['science','Science'],['journeys','Journeys'],['law','Labeling & law'],['all','Full profile']];if(!tabs.some(t=>t[0]===tab))tab='overview';
 const used=new Set();
 const list=(items,cls)=>items?.length?`<ul class="${cls}">${items.map(x=>`<li>${linkTerms(esc(x),undefined,used)}</li>`).join('')}</ul>`:'';
 const faq=g?.faq?.length?`<h3>Frequently asked</h3><div class="faq">${g.faq.map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${linkTerms(esc(a),undefined,used)}</p></details>`).join('')}</div>`:'';
 const guideRefs=g?.refs?.length?`<h3>Guide references</h3><ul class="source-links">${g.refs.map(r=>`<li><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a></li>`).join('')}</ul>`:'';
 const prosCons=g?`<div class="pros-cons"><section><h3>Advantages</h3>${list(g.pros,'pros')}</section><section><h3>Drawbacks</h3>${list(g.cons,'cons')}</section></div>`:'';
 const sections={
  overview:()=>`<h2>Meet ${esc(m.name)}.</h2><p>${esc(m.composition)}</p><h3>How it feels</h3><p>${esc(m.feel)}</p><h3>Where you’ll find it</h3><p>${esc(m.uses)}</p>${detailBlock(m,'origin','Where it comes from',used)}${m.brand?`<div class="notice">${esc(m.type)}. This is a proprietary name, not a new generic fiber classification. <a href="#/fiber/${m.base}">Explore the underlying material →</a></div>`:''}<div class="section-head"><h2>A story woven through time.</h2></div><p>${esc(m.history)}</p><a class="text-link" href="#/fiber/${id}/history">Explore the history ${icon('arrow')}</a>`+prosCons+(g?.notable?.length?`<div class="notice notable"><strong>Worth knowing</strong>${list(g.notable,'notable-list')}</div>`:''),
  types:()=>g?`<h2>Types, grades and fabrics.</h2><h3>Types and grades</h3>${prose(g.types,used)}<h3>Fabrics and products</h3>${prose(g.fabrics,used)}${faq}`:`<h2>Types, grades and fabrics.</h2><p>${esc(m.uses)}</p>`,
  care:()=>`<h2>Buy well, keep it in use.</h2>${g?`<h3>How to judge quality</h3>${prose(g.quality,used)}<h3>Care in detail</h3>${prose(g.care,used)}`:''}<h3>Care at a glance</h3><p>${esc(m.care)}</p>${g?`<h3>Environmental and social footprint</h3>${prose(g.impact,used)}`:''}<h3>Tradeoffs worth understanding</h3><p>${esc(m.tradeoff)}</p><div class="notice"><strong>A useful question to ask</strong><br>${esc(m.question)}</div><p class="muted">Construction, blends, coatings, dyes and trims change appropriate care. The finished product's label and producer instructions take priority over general fiber guidance.</p>${guideRefs}<a class="text-link" href="#/article/care-for-longer">Read the care field note ${icon('arrow')}</a>`,
  history:()=>`<h2>The story of ${esc(m.name)}.</h2><div class="history-block"><span class="history-icon">01</span><div><h3>From origin to use</h3><p>${esc(m.history)}</p></div></div>${m.detail?.past?`<div class="history-block"><span class="history-icon">02</span><div><h3>The deeper record</h3>${prose(m.detail.past,used)}</div></div>`:''}<div class="history-block"><span class="history-icon">${m.detail?.past?'03':'02'}</span><div><h3>The material today</h3><p>${esc(m.composition)} ${esc(m.uses)}</p></div></div><div class="history-block"><span class="history-icon">${m.detail?.past?'04':'03'}</span><div><h3>The next question</h3><p>${esc(m.question)}</p></div></div><div class="notice">This is a concise historical overview. Precise first-use dates are omitted where the evidence depends on region, product form or disputed attribution.</div>`,
  science:()=>`<h2>Inside the material.</h2><div class="eyebrow">CHEMISTRY & STRUCTURE</div><h3>${esc(sci[0])}</h3><p>${esc(sci[1])}</p>${detailBlock(m,'structure','Structure & chemistry',used)}${detailBlock(m,'process','From source to yarn',used)}${detailBlock(m,'performance','Performance in use',used)}${detailBlock(m,'identify','How it is identified',used)}<h3>From fiber to fabric</h3><p>${esc(m.feel)} The final textile also depends on fiber length, yarn preparation, twist, knit or weave, and finishing.</p><h3>What a label cannot measure</h3><p>A material name alone cannot establish warmth, durability or comfort. Comparable tests need the same conditions and a defined product construction. The atlas uses qualitative descriptions rather than unsupported performance scores.</p><a class="button primary" href="#/science">Open the science lab ${icon('arrow')}</a>`,
  journeys:()=>js.length?`<h2>Follow a possible path.</h2><p>Explore ${js.length} named routes through this material’s atlas model. Each connects approximate places and processing stages, without claiming a verified supplier relationship.</p><div class="route-grid profile-routes">${js.map(routeCard).join('')}</div>`:`<h2>A profile without an invented route.</h2><p>This entry has material, historical and technical context. A geographic supply-chain model has not been added. The linked references are a starting point for finding documented producers.</p>${m.brand&&networks[m.base]?`<a class="button" href="#/atlas/${m.base}">Explore the underlying fiber atlas ${icon('arrow')}</a>`:'<a class="button" href="#/journeys">Browse mapped materials →</a>'}`,
  law:()=>`<h2>Labeling, law and standards.</h2>${m.detail?.labeling?prose(m.detail.labeling,used):'<p>No entry-specific labeling notes yet.</p>'}<p class="muted">This describes what rules and standards cover. It is not legal advice; jurisdiction, product form and current rule text control.</p>${m.brand?`<div class="notice">${esc(m.type)}. A trademark is not a generic fiber name; labels still need the generic name.</div>`:''}`
 };
 const body=tab==='all'?`<div class="full-profile">${tabs.filter(([k])=>k!=='all').map(([k,name])=>`<section class="profile-section" id="section-${k}"><div class="eyebrow">${esc(name.toUpperCase())}</div>${sections[k]()}</section>`).join('')}<button class="button" data-action="print">Print this profile</button></div>`:sections[tab]();
 const ids=[...m.sources];if(id==='nylon')ids.push('nylon-history');if(['wool','cotton','silk','cashmere'].includes(id))ids.push('trade-history');
 $('#main').innerHTML=`<div class="page">${breadcrumb([['Materials','#/materials'],[m.name]])}<section class="profile-hero"><div><div class="eyebrow">MATERIAL ${String(m.index).padStart(3,'0')} · ${esc(m.family)}</div><h1>${esc(m.name)}</h1><p class="dek">${esc(m.tagline)}</p><div class="actions">${networks[id]?`<a class="button primary" href="#/atlas/${id}">Find it on the atlas ${icon('globe')}</a>`:''}<a class="button" href="#/compare?ids=${id},${id==='wool'?'linen':'wool'},cotton">Compare ${icon('compare')}</a>${saveButton(id)}<button class="button small" data-action="share">${icon('share')} Share</button><a class="button small" href="materials/${id}/index.html">Reading edition ↗</a></div></div><div class="swatch-art ${id==='wool'?'wool':id==='silk'?'silk':''}" style="--swatch:${m.color}"><span class="fiber-ring"></span><span class="profile-art-label">${esc(m.name).toUpperCase()} / ABSTRACT TEXTILE STUDY</span></div></section><nav class="profile-tabs" aria-label="Material sections">${tabs.map(([key,name])=>`<a href="#/fiber/${id}/${key}" ${tab===key?'aria-current="page"':''}>${name}</a>`).join('')}</nav><div class="profile-body"><article class="reading">${m.legacyOnly?'<div class="notice">Specialty archive. Original geographic connections and supplier claims are unverified. No current commercial volumes or performance rankings are asserted.</div>':''}${body}</article><aside><section class="fact-box"><h3>At a glance</h3><div class="fact-row"><small>Family</small>${esc(m.family)}</div><div class="fact-row"><small>Entry type</small>${m.brand?esc(m.type):m.legacyOnly?'Specialty / legacy material':'Fiber or material reference'}</div><div class="fact-row"><small>Map coverage</small>${js.length?js.length+' illustrative journeys':'Reference profile'}</div><div class="fact-row"><small>Science</small>${esc(sci[0])}</div>${m.aliases?`<div class="fact-row"><small>Related search terms</small>${esc(m.aliases)}</div>`:''}</section>${evidenceBox(m)}<section class="fact-box"><h3>Read the sources</h3>${sourceList(ids)}<small class="muted">References explain materials and processes. They do not verify each modeled trade connection.</small></section>${citeBox(m)}</aside></div></div>`;
}
function routeCard(j){const m=byId[j.fiber];return `<article class="route-card"><div class="eyebrow">${esc(m.name)} · ${j.stops.length} STAGES</div><h3><a href="#/journey/${j.id}">${esc(j.title)}</a></h3><div class="route-path">${j.stops.map(n=>esc(n.name)).join(' → ')}</div><div class="route-meta"><span>${j.countries.length} countries · ${j.km.toLocaleString()} km*</span><a href="#/journey/${j.id}" aria-label="Explore ${esc(m.name)} journey ${esc(j.title)}">Explore ↗</a></div></article>`;}
function routesPage(r){title('Journey library');const q=r.params.get('q')||'',fiber=r.params.get('fiber')||'all',sort=r.params.get('sort')||'featured';$('#main').innerHTML=`<div class="page"><div class="page-intro"><div class="eyebrow">THE JOURNEY LIBRARY</div><h1>Follow a different thread.</h1><p>Explore ${journeys.length} curated paths from the atlas model. Search a material, a city or a country to see how the stages connect.</p></div><div class="toolbar"><label class="search-field">${icon('search')}<input id="journey-search" type="search" value="${esc(q)}" placeholder="Try Biella, Mongolia, or linen…" aria-label="Search journeys"></label><label>Material <select id="journey-fiber"><option value="all">All mapped fibers</option>${getMaterials({mapped:true,sort:'az'}).map(m=>`<option value="${m.id}" ${fiber===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><label>Sort <select id="journey-sort">${[['featured','Featured'],['az','Origin: A–Z'],['za','Origin: Z–A'],['distance-asc','Distance: shortest'],['distance-desc','Distance: longest'],['stages','Most stages'],['stages-asc','Fewest stages'],['material','Material: A–Z']].map(([id,t])=>`<option value="${id}" ${sort===id?'selected':''}>${t}</option>`).join('')}</select></label><span class="result-count" id="journey-count" aria-live="polite"></span></div><div id="journey-results"></div><div class="notice">*Distances sum great-circle segments between approximate markers. They exclude shipping detours and local collection. They are not transport or emissions estimates. Route links are illustrative; specialty legacy concepts remain unverified.</div></div>`;
 let page=Math.max(1,Number(r.params.get('page'))||1);
 function draw(reset=false){if(reset)page=1;const q=$('#journey-search').value,fiber=$('#journey-fiber').value,sort=$('#journey-sort').value;let list=journeys.filter(j=>(fiber==='all'||j.fiber===fiber)&&normalize([byId[j.fiber].name,j.title,...j.countries,...j.stops.map(n=>n.name)].join(' ')).includes(normalize(q)));if(sort==='az')list.sort((a,b)=>a.title.localeCompare(b.title));if(sort==='za')list.sort((a,b)=>b.title.localeCompare(a.title));if(sort==='distance-asc')list.sort((a,b)=>a.km-b.km);if(sort==='distance-desc')list.sort((a,b)=>b.km-a.km);if(sort==='stages')list.sort((a,b)=>b.stops.length-a.stops.length);if(sort==='stages-asc')list.sort((a,b)=>a.stops.length-b.stops.length);if(sort==='material')list.sort((a,b)=>byId[a.fiber].name.localeCompare(byId[b.fiber].name)||a.title.localeCompare(b.title));page=Math.min(page,Math.ceil(list.length/12)||1);setQuery({q,fiber:fiber==='all'?'':fiber,sort,page});$('#journey-count').textContent=list.length+' journeys';$('#journey-results').innerHTML=list.length?`<div class="route-grid">${list.slice((page-1)*12,page*12).map(routeCard).join('')}</div>${pager(page,list.length)}`:empty('No routes match.','Try another place, or choose all mapped fibers.');}
 ['journey-search','journey-fiber','journey-sort'].forEach(id=>$('#'+id).addEventListener(id==='journey-search'?'input':'change',()=>draw(true)));
 $('#main').addEventListener('click',e=>{const p=e.target.closest('[data-page]');if(p){page=Number(p.dataset.page);draw();$('#journey-results').scrollIntoView();}});draw();
}
function journeyPage(id){const j=journeyById[id];if(!j)return notFound();const m=byId[j.fiber];title(j.title+' · '+m.name);$('#main').innerHTML=`<div class="page">${breadcrumb([['Journeys','#/journeys'],[j.title]])}<section class="journey-hero"><div><div class="eyebrow">${esc(m.name)} · ${j.status.toUpperCase()}</div><h1>${esc(j.title)}</h1><p>${esc(m.tagline)} Follow this possible sequence through collection, transformation and a destination market.</p><div class="actions"><a class="button primary" href="#/atlas/${m.id}?journey=${j.id}">Open interactive atlas ${icon('globe')}</a><button class="button" data-download="${j.id}">${icon('download')} Download route</button><button class="button" data-action="share">${icon('share')} Share</button></div></div><div class="mini-map" id="journey-globe"></div></section><div class="stats-banner"><div><b>${j.stops.length}</b><span>MODELED STAGES</span></div><div><b>${j.countries.length}</b><span>COUNTRIES</span></div><div><b>${j.km.toLocaleString()}</b><span>GREAT-CIRCLE KM</span></div><div><b>${j.status==='Legacy concept'?'Legacy':'Model'}</b><span>EVIDENCE STATUS</span></div></div><div class="notice">${j.status==='Legacy concept'?'This route was inherited from the original atlas and remains unverified.':'This is an educational route model, not a record of actual shipments or a verified brand supply chain.'} Technical references support general processes; they do not establish these commercial relationships.</div><ol class="full-stops">${j.stops.map((n,i)=>`<li><span class="step-number">${String(i+1).padStart(2,'0')}</span><div><div class="eyebrow">${esc(n.role)}</div><h3>${esc(n.name)}</h3><small>${esc(n.country)} · ${esc(n.sub)}</small></div><div><p>${esc(processNote(n,m))}</p><small>${n.lat.toFixed(2)}°, ${n.lon.toFixed(2)}° · Approximate geographic marker</small></div></li>`).join('')}</ol><div class="profile-body"><section class="reading"><h2>What travels between the dots?</h2><p>Raw fiber, prepared top, yarn, fabric and finished garments are different products. The diagram simplifies intermediate warehouses, ports, finishing operations and commercial handoffs. Ask suppliers which material form crosses each stage.</p><h3>One question to keep with you</h3><p>${esc(m.question)}</p><a class="text-link" href="#/fiber/${m.id}">Read the full ${esc(m.name)} profile ${icon('arrow')}</a></section><aside class="fact-box"><h3>Process references</h3>${sourceList(m.sources)}</aside></div></div>`;globe=new Globe($('#journey-globe'),networks[m.id],j,()=>{},{spin:false});globe.flat=true;globe.render();}
function compareValue(m,key){if(key==='facts')return (m.detail?.facts||[]).map(([k,v])=>`<strong>${esc(k)}:</strong> ${esc(v)}`).join('<br>');const gv=['types','fabrics','pros','cons'].includes(key)?m.guide?.[key]:null;if(Array.isArray(gv))return gv.map(esc).join('<br>');return esc(gv??m[key]??m.detail?.[key]??'');}
function comparePage(r){title('Compare materials');let ids=(r.params.get('ids')||'wool,linen,polyester').split(',').filter(id=>byId[id]).slice(0,3);if(!ids.length)ids=['wool','linen','polyester'];while(ids.length<3)ids.push(['cotton','silk','cashmere'].find(x=>!ids.includes(x)));ids=[...new Set(ids)];while(ids.length<3)ids.push(materials.find(m=>!ids.includes(m.id)).id);const sorted=[...materials].sort((a,b)=>a.name.localeCompare(b.name));$('#main').innerHTML=`<div class="page"><div class="page-intro"><div class="eyebrow">SIDE BY SIDE</div><h1>Different fibers. Better questions.</h1><p>Compare three materials by composition, feel, use and care. These qualitative descriptions are a starting point, not a universal performance ranking.</p></div><p class="mobile-only muted">Swipe the table horizontally to compare all three materials.</p><div class="comparison-wrap" tabindex="0" role="region" aria-label="Material comparison, scroll horizontally on smaller screens"><table class="comparison"><caption class="sr-only">Three materials compared by composition, feel, uses, science, history, care and sourcing</caption><thead><tr><th scope="col">Choose your materials</th>${ids.map((id,i)=>`<th scope="col"><label class="sr-only" for="compare-${i}">Material ${i+1}</label><select id="compare-${i}" data-compare="${i}">${sorted.map(m=>`<option value="${m.id}" ${m.id===id?'selected':''}>${esc(m.name)}</option>`).join('')}</select><h3>${esc(byId[id].name)}</h3><a class="text-link" href="#/fiber/${id}">Read profile ↗</a></th>`).join('')}</tr></thead><tbody>${[['Family','family'],['Composition','composition'],['Source & geography','origin'],['Structure & chemistry','structure'],['Feel & behavior','feel'],['Performance in use','performance'],['Key figures','facts'],['Common uses','uses'],['Types & grades','types'],['Fabrics & products','fabrics'],['Advantages','pros'],['Drawbacks','cons'],['History','history'],['Labeling & law','labeling'],['Care','care'],['Tradeoffs','tradeoff'],['Ask the maker','question']].filter(([,key])=>ids.some(id=>compareValue(byId[id],key))).map(([label,key])=>`<tr><th scope="row">${label}</th>${ids.map(id=>`<td>${compareValue(byId[id],key)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="notice">Fabric construction, finish and test conditions can change performance substantially. No numeric softness, warmth or sustainability score is assigned to a generic fiber.</div><div class="actions"><button class="button" data-action="share">${icon('share')} Share comparison</button><a class="button" href="#/science">Understand the science ${icon('arrow')}</a></div></div>`;$$('[data-compare]').forEach(el=>el.addEventListener('change',()=>{const next=$$('[data-compare]').map(x=>x.value);if(new Set(next).size!==next.length){toast('Choose three different materials.');el.value=ids[Number(el.dataset.compare)];return;}location.hash=href('compare','',{ids:next.join(',')});}));}
function regionCards(list=regions){return list.map((r,i)=>`<a class="region-card" href="#/region/${r.id}"><div class="region-art" style="--region:${r.color}"><span>REGION ${String(i+1).padStart(2,'0')}</span></div><div class="region-card-content"><h3>${esc(r.name)}</h3><p>${esc(r.subtitle)} ↗</p></div></a>`).join('');}
function regionsPage(){title('Places & regions');$('#main').innerHTML=`<div class="page"><div class="page-intro"><div class="eyebrow">A GEOGRAPHY OF MATERIALS</div><h1>Places shape the thread.</h1><p>Growing conditions, local knowledge, mills and trade connect the world of textiles. Start with a region to see the materials and modeled journeys that touch it.</p></div><div class="region-grid">${regionCards()}</div></div>`;}
function regionPage(id){const r=regions.find(x=>x.id===id);if(!r)return notFound();title(r.name);const js=journeys.filter(j=>j.countries.some(c=>r.countries.includes(c)));const ms=[...new Set(js.map(j=>j.fiber))].map(id=>byId[id]);$('#main').innerHTML=`<div class="page">${breadcrumb([['Regions','#/regions'],[r.name]])}<div class="page-intro"><div class="eyebrow">${esc(r.subtitle)}</div><h1>${esc(r.name)}</h1><p>${esc(r.intro)}</p></div><div class="notice"><strong>Ask about this region</strong><br>${esc(r.question)}</div><div class="section-head"><h2>Materials in the model</h2><span class="result-count">${ms.length} mapped materials</span></div><div class="library-grid">${ms.map(materialCard).join('')}</div><div class="section-head"><h2>A few paths to follow</h2><a class="text-link" href="#/journeys">All journeys ${icon('arrow')}</a></div><div class="route-grid">${js.slice(0,6).map(routeCard).join('')}</div></div>`;}
function articleCard(a,i){return `<article class="article-card"><a href="#/article/${a.id}"><div class="article-art" style="background:${['#e6e9dd','#ece3d3','#e2e9e3','#e8e1db'][i%4]}"><span>${['Aa','↗','≈','∞','C','↺','◉','?'][i%8]}</span></div><div class="eyebrow">${esc(a.tag)} · ${a.time} MIN READ</div><h3>${esc(a.title)}</h3><p>${esc(a.dek)}</p><small>Read the field note ↗</small></a></article>`;}
function learnPage(){title('Field notes');$('#main').innerHTML=`<div class="page"><div class="page-intro"><div class="eyebrow">THE FIELD NOTES</div><h1>Look a little closer.</h1><p>Understand the language, craft and tradeoffs of textiles. A reading collection for the curious, from a clothing label to the structure of a thread.</p></div><div class="article-grid">${articles.map(articleCard).join('')}</div><div class="section-head"><h2>Keep exploring.</h2></div><div class="discovery-grid"><a class="fact-box" href="#/science"><div class="eyebrow">INTERACTIVE</div><h3>The science lab</h3><p>Explore weave structures, chemistry and fiber dimensions. ↗</p></a><a class="fact-box" href="#/history"><div class="eyebrow">THROUGH TIME</div><h3>Fiber histories</h3><p>Browse the historical context for all 100 entries. ↗</p></a><a class="fact-box" href="#/glossary"><div class="eyebrow">THE LANGUAGE</div><h3>A textile glossary</h3><p>From bast to worsted, get to know the terms. ↗</p></a></div></div>`;}
function articlePage(id){const a=articles.find(x=>x.id===id);if(!a)return notFound();title(a.title);$('#main').innerHTML=`<div class="page">${breadcrumb([['Field notes','#/learn'],[a.tag]])}<header class="article-heading"><div class="eyebrow">${esc(a.tag)} · ${a.time} MIN READ</div><h1>${esc(a.title)}</h1><p>${esc(a.dek)}</p></header><div class="article-layout"><aside><div class="eyebrow">IN THIS FIELD NOTE</div>${a.sections.map(([h],i)=>`<a href="#section-${i}" data-scroll="section-${i}">${esc(h)}</a>`).join('')}<a href="#/learn">← All field notes</a></aside><article class="reading">${a.sections.map(([h,p],i)=>`<section id="section-${i}"><h2>${esc(h)}</h2><p>${esc(p)}</p></section>`).join('')}<h3>References</h3>${sourceList(a.sources)}<div class="actions"><button class="button" data-action="share">${icon('share')} Share this note</button><a class="button" href="#/sources">Sources & methodology</a></div></article></div><div class="section-head"><h2>Meet the materials.</h2></div><div class="discovery-grid">${a.fibers.map(id=>`<a class="discovery-card" href="#/fiber/${id}">${swatch(byId[id])}<div class="discovery-copy"><div class="eyebrow">${esc(byId[id].family)}</div><h3>${esc(byId[id].name)}</h3><p>Open material profile ↗</p></div></a>`).join('')}</div></div>`;}
// Glossary sort orders; 'relevance' keeps ranked order while searching and A to Z otherwise.
function sortTerms(results,sort){const by={az:(a,b)=>a.term.term.localeCompare(b.term.term,'en'),za:(a,b)=>b.term.term.localeCompare(a.term.term,'en'),topic:(a,b)=>a.term.category.localeCompare(b.term.category)||a.term.term.localeCompare(b.term.term,'en')}[sort];return by?[...results].sort(by):results;}
function glossaryPage(r){
 if(r.id){const t=glossaryById[r.id];if(!t)return notFound('This glossary term could not be found.');title(t.term+' definition');$('#main').innerHTML=`<article class="page glossary-article"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="#/glossary">Textile glossary</a><span> / ${esc(t.term)}</span></nav><div class="eyebrow">${esc(t.category)}</div><h1>${esc(t.term)}</h1><p class="muted">Also searched as: ${t.aliases.map(esc).join(', ')}</p><div class="reading">${termBody(t)}</div></article>`;return;}
 title('Textile glossary: fiber, fabric and processing definitions');$('#main').innerHTML=`<div class="page"><div class="page-intro"><div class="eyebrow">THE LANGUAGE OF TEXTILES</div><h1>Textile glossary.</h1><p>Understand fibers, fabric construction, measurements and material claims. Explore ${glossaryEntries.length} detailed definitions with the science behind each term, practical examples, useful distinctions, origins and sources.</p><a class="text-link" href="glossary/index.html">Open the reading edition ↗</a></div><div class="toolbar"><label class="search-field">${icon('search')}<input type="search" id="glossary-search" value="${esc(r.params.get('q')||'')}" placeholder="Search terms, science, history…" aria-label="Search glossary"></label><label>Topic <select id="glossary-category"><option value="">All topics</option>${glossaryCategories.map(c=>`<option ${r.params.get('category')===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Sort <select id="glossary-sort">${[['relevance','Best match / A–Z'],['az','A–Z'],['za','Z–A'],['topic','Topic, then term']].map(([v,t])=>`<option value="${v}" ${(r.params.get('sort')||'relevance')===v?'selected':''}>${t}</option>`).join('')}</select></label><button class="button small" id="glossary-reset">Reset</button><span id="glossary-count" class="result-count" aria-live="polite"></span><button class="button small" data-action="expand-glossary">Expand all</button></div><nav class="family-chips" aria-label="Filter glossary by letter">${['',...[...new Set(glossaryEntries.map(t=>t.term[0]))].sort()].map(l=>`<button class="chip" data-letter="${l}" aria-pressed="${l===(r.params.get('letter')||'')}">${l||'All letters'}</button>`).join('')}</nav><div id="glossary-results" class="glossary-list"></div></div>`;
 let letter=r.params.get('letter')||'';
 function draw(){const q=$('#glossary-search').value,category=$('#glossary-category').value;const sort=$('#glossary-sort').value;setQuery({q,category,letter,sort:sort==='relevance'?'':sort});const results=sortTerms(searchTerms({q,category,letter}),sort),list=results.map(r=>r.term);const hint=list.length||!q.trim()?null:suggestTerms(q);$('#glossary-count').textContent=list.length+' terms';$('#glossary-results').innerHTML=list.length?results.map(({term:t,matched})=>{const key=['definition','explanation','deeper','origins','example','caution'].find(k=>matched[k]);return `<details><summary>${esc(t.term)}<small>${esc(t.category)}</small></summary><p>${esc(t.definition)}</p>${key&&key!=='definition'?`<p class="match-snippet"><small>${esc(glossaryFieldLabels[key])}</small> ${snippet(t[key],matched[key],170)}</p>`:`<p>${esc(t.explanation)}</p>`}<a class="text-link" href="#/glossary/${t.id}">Read the full ${esc(t.term.toLowerCase())} definition ↗</a></details>`;}).join(''):empty('No terms found.',(hint?`Did you mean <button class="text-link" data-term-suggest="${esc(hint)}">${esc(hint)}</button>? `:'')+'Reset the filters or try another spelling.');$('[data-action="expand-glossary"]').textContent='Expand all';$$('[data-letter]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.letter===letter));}
 $('#glossary-search').addEventListener('input',draw);$('#glossary-results').addEventListener('click',e=>{const b=e.target.closest('[data-term-suggest]');if(b){$('#glossary-search').value=b.dataset.termSuggest;draw();}});$('#glossary-category').addEventListener('change',draw);$('#glossary-sort').addEventListener('change',draw);$$('[data-letter]').forEach(b=>b.addEventListener('click',()=>{letter=b.dataset.letter;draw();}));$('#glossary-reset').addEventListener('click',()=>{$('#glossary-search').value='';$('#glossary-category').value='';$('#glossary-sort').value='relevance';letter='';draw();});draw();
}
function historyPage(r){title('Fiber histories');$('#main').innerHTML=`<div class="page"><div class="page-intro"><div class="eyebrow">MATERIALS THROUGH TIME</div><h1>Before it became a label.</h1><p>Cloth carries histories of craft, trade, invention and labor. Explore concise historical context for each material, then follow its references.</p></div><div class="toolbar"><label class="search-field">${icon('search')}<input id="history-search" type="search" value="${esc(r.params.get('q')||'')}" placeholder="Search a material or historical theme…" aria-label="Search fiber histories"></label><label>Family <select id="history-family">${families.map(f=>`<option ${r.params.get('family')===f?'selected':''}>${esc(f)}</option>`).join('')}</select></label><label>Sort <select id="history-sort">${[['az','A–Z'],['za','Z–A'],['family','Family, then name']].map(([v,t])=>`<option value="${v}" ${(r.params.get('sort')||'az')===v?'selected':''}>${t}</option>`).join('')}</select></label><span id="history-count" class="result-count" aria-live="polite"></span></div><div id="history-results"></div></div>`;let page=1;function draw(reset=false){if(reset)page=1;const q=$('#history-search').value,family=$('#history-family').value;const list=materials.filter(m=>(family==='All materials'||m.family===family)&&normalize(m.name+' '+m.history).includes(normalize(q))).sort((a,b)=>{const sort=$('#history-sort').value;return sort==='za'?b.name.localeCompare(a.name):sort==='family'?a.family.localeCompare(b.family)||a.name.localeCompare(b.name):a.name.localeCompare(b.name);});page=Math.min(page,Math.ceil(list.length/12)||1);setQuery({q,family,sort:$('#history-sort').value==='az'?'':$('#history-sort').value});$('#history-count').textContent=list.length+' histories';$('#history-results').innerHTML=list.length?`<div class="history-grid">${list.slice((page-1)*12,page*12).map(m=>`<article class="history-item"><div class="eyebrow">${esc(m.family)}</div><h3><a href="#/fiber/${m.id}/history">${esc(m.name)}</a></h3><p>${esc(m.history)}</p><a class="text-link" href="#/fiber/${m.id}/history">Profile & references ↗</a></article>`).join('')}</div>${pager(page,list.length)}`:empty('No histories found.','Try another name or a broader family.');}$('#history-search').addEventListener('input',()=>draw(true));$('#history-family').addEventListener('change',()=>draw(true));$('#history-sort').addEventListener('change',()=>draw(true));$('#main').addEventListener('click',e=>{const p=e.target.closest('[data-page]');if(p){page=Number(p.dataset.page);draw();$('#history-results').scrollIntoView();}});draw();}
function sciencePage(){title('Science lab');$('#main').innerHTML=`<div class="page"><div class="page-intro"><div class="eyebrow">THE SCIENCE LAB</div><h1>A closer look at the thread.</h1><p>Explore how chemistry becomes a fiber, how yarn becomes fabric, and why a single material name can never tell the whole story.</p></div><div class="lab-grid"><section class="lab"><div class="eyebrow">01 / FABRIC STRUCTURE</div><h3>Weave a little understanding.</h3><p>Switch structures to see which yarn passes over the other. Green is warp; gold is weft.</p><div class="segmented" aria-label="Weave structure"><button data-weave="plain" aria-pressed="true">Plain</button><button data-weave="twill" aria-pressed="false">2/2 twill</button><button data-weave="satin" aria-pressed="false">5-end satin</button></div><div class="weave-layout"><div id="weave-grid" class="weave-grid" role="img" aria-label="Plain weave interlacing diagram"></div><p id="weave-description" aria-live="polite"></p></div><small>Schematic only. Yarn spacing, scale and surface texture are simplified.</small></section><section class="lab"><div class="eyebrow">02 / FIBER DIMENSIONS</div><h3>What does denier mean?</h3><p>Denier is linear mass, not diameter. Estimate the diameter of an ideal, solid, circular filament.</p><label>Linear density (denier)<input id="denier" type="number" min="0.01" max="100000" step="0.1" value="5"></label><label>Material density (g/cm³)<input id="density" type="number" min="0.01" max="30" step="0.01" value="1.38"></label><output id="diameter" aria-live="polite"></output><small id="tex-result"></small><small>Assumes a single circular, nonporous filament and a specified density. Multifilament yarns, hollow fibers and irregular cross-sections do not meet this model.</small></section><section class="lab"><div class="eyebrow">03 / YARN COUNT</div><h3>Translate between count systems.</h3><p>Direct systems weigh a fixed length; indirect systems measure the length in a fixed weight, so higher Nm or Ne means finer yarn.</p><div class="converter"><label>Value<input id="count-value" type="number" min="0.001" step="any" value="30"></label><label>Unit<select id="count-unit">${countUnits.map(([v,t])=>`<option value="${v}" ${v==='ne'?'selected':''}>${t}</option>`).join('')}</select></label></div><table class="convert-table"><tbody id="count-out"></tbody></table><small>Exact unit conversions. Plied yarns are often written as a count per ply (for example 2/60 Nm); convert the resultant yarn, not the singles.</small></section><section class="lab"><div class="eyebrow">04 / FABRIC WEIGHT</div><h3>Compare fabric weights.</h3><p>Fabric weight is mass per area. Silk is traded in momme; many other fabrics use g/m² or oz/yd².</p><div class="converter"><label>Value<input id="weight-value" type="number" min="0.001" step="any" value="19"></label><label>Unit<select id="weight-unit">${weightUnits.map(([v,t])=>`<option value="${v}" ${v==='momme'?'selected':''}>${t}</option>`).join('')}</select></label></div><table class="convert-table"><tbody id="weight-out"></tbody></table><small>1 oz/yd² = 33.906 g/m². One momme is the weight in pounds of a piece 45 in × 100 yd, about 4.340 g/m². Some traders use linear oz per yard of goods instead; check which basis a listing uses.</small></section></div><div class="section-head"><h2>Six ideas to keep in mind.</h2></div><div class="science-grid">${scienceTopics.map(([id,h,dek,p],i)=>`<article class="science-card" id="science-${id}"><div class="eyebrow">${String(i+1).padStart(2,'0')} / ${id.toUpperCase()}</div><h3>${h}</h3><p><strong>${dek}</strong></p><p>${p}</p></article>`).join('')}</div><div class="notice">The diameter model uses d = √(4000 × denier / (9π × density)), with d in micrometers and density in g/cm³. Tex = denier ÷ 9. It is a dimensional calculation, not a softness test or material certification.</div><div class="profile-body"><section class="reading"><h2>Test the fabric, not just the name.</h2><p>A useful comparison defines temperature, humidity, sample construction, conditioning and method. This atlas deliberately avoids converting qualitative descriptions into artificial laboratory scores.</p><a class="button" href="#/compare">Compare material descriptions ${icon('arrow')}</a></section><aside class="fact-box"><h3>Technical starting points</h3>${sourceList(['woolmark','lenzing','manufactured'])}</aside></div></div>`;
 updateWeave('plain');const update=()=>{const d=Number($('#denier').value),rho=Number($('#density').value);if(!Number.isFinite(d)||!Number.isFinite(rho)||d<.01||rho<.01||d>100000||rho>30){$('#diameter').textContent='Enter valid positive values.';$('#tex-result').textContent='Use denier 0.01–100,000 and density 0.01–30 g/cm³.';return;}$('#diameter').textContent=diameterFromDenier(d,rho).toFixed(2)+' μm';$('#tex-result').textContent=(d/9).toFixed(3)+' tex · idealized diameter';};$('#denier').addEventListener('input',update);$('#density').addEventListener('input',update);update();
 const fmt=n=>Number.isFinite(n)?(n>=100?n.toFixed(1):n>=1?n.toFixed(2):n.toPrecision(3)):'n/a';
 const convert=(value,unit,units,to,from,out)=>()=>{const base=to($(value).value,$(unit).value);$(out).innerHTML=Number.isFinite(base)?units.map(([v,t])=>`<tr${v===$(unit).value?' class="current"':''}><th scope="row">${t}</th><td>${fmt(from(base,v))}</td></tr>`).join(''):'<tr><td>Enter a positive value.</td></tr>';};
 const counts=convert('#count-value','#count-unit',countUnits,toTex,fromTex,'#count-out'),weights=convert('#weight-value','#weight-unit',weightUnits,toGsm,fromGsm,'#weight-out');
 ['#count-value','#count-unit'].forEach(x=>$(x).addEventListener('input',counts));['#weight-value','#weight-unit'].forEach(x=>$(x).addEventListener('input',weights));counts();weights();}
function updateWeave(type){const definitions={plain:'Each warp yarn alternates over and under consecutive weft yarns. Adjacent rows reverse the pattern.',twill:'A two-over, two-under repeat shifts by one position each row, creating a diagonal pattern.',satin:'A five-end, four-over/one-under repeat distributes the binding points. Longer floats can create a smoother-looking surface.'};$('#weave-grid').innerHTML=Array.from({length:100},(_,i)=>{const x=i%10,y=Math.floor(i/10);const over=type==='plain'?(x+y)%2===0:type==='twill'?(x+y)%4<2:(x+2*y)%5!==0;return `<span class="${over?'':'weft'}"></span>`;}).join('');$('#weave-grid').setAttribute('aria-label',type+' weave: '+definitions[type]);$('#weave-description').textContent=definitions[type];$$('[data-weave]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.weave===type));}
function sourcesPage(){title('Sources & methodology');$('#main').innerHTML=`<div class="page"><div class="page-intro"><div class="eyebrow">READING THE ATLAS</div><h1>Curiosity, with a paper trail.</h1><p>Material references, transparent limits and a clear distinction between a geographic model and a verified supply chain.</p></div><div class="profile-body"><article class="reading"><h2>What the atlas shows</h2><p>Fibers of Earth contains ${materials.length} material and technology entries, ${Object.keys(networks).length} mapped material networks, ${journeys.length} named illustrative journeys and ${locations.length} distinct location labels. Counts refer to this edition’s dataset, not the size of the global textile industry.</p><h3>Three kinds of information</h3><p><strong>Material context:</strong> editorial descriptions informed by technical, institutional and producer references. <strong>Illustrative routes:</strong> modeled links between approximate places and stages. <strong>Legacy concepts:</strong> specialty connections inherited from the earlier atlas that have not been independently verified.</p><h3>What a source supports</h3><p>A technical article may explain scouring without verifying a particular mill-to-mill shipment. Producer pages establish how a company describes its technology; they are not independent proof of every environmental or performance claim. Historical summaries omit unsupported exact dates.</p><h3>Map and distance</h3><p>The bundled map uses generalized Natural Earth geometry through World Atlas. Markers represent approximate cities or regions. Distance sums great-circle segments using a spherical Earth radius of 6,371 km. It excludes real transport paths and cannot be converted directly into carbon emissions.</p><h3>Coverage and terminology</h3><p>The library includes generic fibers, selected named variants, fillings, historical materials and proprietary technologies. A branded fiber, recycled feedstock, sourcing program and yarn technology are labeled distinctly. No finite catalog can include every plant species, formulation, trademark or experimental material.</p><h3>Editorial maintenance</h3><p>Edition 2.2, prepared September 2026. Research profiles and glossary additions carry an evidence level and entry-specific references. Selected technical and producer sources were reviewed during the update; coverage is not a complete fact-check of every historical or geographic claim. Corrections and stronger primary references are welcome through the project repository.</p><button class="button" data-action="export-data">${icon('download')} Download atlas data (JSON)</button></article><aside><section class="fact-box"><h3>What we do not infer</h3><p>No live shipment tracking, market-volume weighting, supplier certification, carbon calculator or universal sustainability score is implied by the map.</p></section><section class="fact-box"><h3>Historical data</h3><p>When the 2025 Textile Exchange report is cited, it describes 2024 production. Older technical references are used for material context, not current market shares.</p></section></aside></div><div class="section-head"><h2>The reference shelf.</h2><span class="result-count">${sources.length} references</span></div><div class="source-grid">${sources.map(s=>`<article class="source-card"><div class="eyebrow">${s.id.startsWith('brand-')?'PRODUCER REFERENCE':'REFERENCE'}</div><h3>${esc(s.name)}</h3><p><strong>${esc(s.title)}</strong></p><p>${esc(s.note)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Open source ↗</a></article>`).join('')}</div></div>`;}
function aboutPage(){title('About');$('#main').innerHTML=`<div class="page legal-layout"><div class="eyebrow">ABOUT THIS PROJECT</div><h1>The world is in what we wear.</h1><p>Fibers of Earth is an independent textile atlas by Chaos. It connects materials, places, histories and science so that a familiar label can become the beginning of a better question.</p><h2>Explore in four directions.</h2><p><strong>Atlas</strong> follows an illustrative fiber journey. <strong>Materials</strong> offers profiles, comparisons and saved collections. <strong>Journeys</strong> explores routes and regions. <strong>Learn</strong> connects field notes, science, history and terminology.</p><h2>Made for curiosity.</h2><p>The atlas is an educational reference, not a supplier directory or a record of actual shipments. No brand partnership, certification or endorsement is implied. Proprietary names belong to their respective owners.</p><h2>A local-first field guide.</h2><p>Content, search, interactive tools and the base map are bundled, so the core atlas works offline. When hosted, detailed coastlines load from the same site as you zoom in. No account is required. Bookmarks stay in your browser. External references open only when you follow their links.</p><div class="actions"><a class="button primary" href="#/atlas/wool">Explore the atlas ${icon('arrow')}</a><a class="button" href="#/sources">Sources & method</a><a class="button" href="https://github.com/SharpMeow/FibersOfEarth" target="_blank" rel="noopener noreferrer">Project repository ↗</a></div></div>`;}
function privacyPage(){title('Privacy');$('#main').innerHTML=`<div class="page legal-layout"><div class="eyebrow">YOUR FIELD GUIDE, YOUR DEVICE</div><h1>Privacy, simply.</h1><h2>What stays in your browser</h2><p>The site stores only your saved material IDs (fibersOfEarth.saved.v2) and your display settings (fibersOfEarth.display.v1) in local storage. If storage is unavailable, both work for the current session. Clearing saved materials leaves display settings alone; use Restore defaults in Display settings to clear those. Search and comparison choices operate locally and may appear in the URL so that views can be shared.</p><h2>What leaves your device</h2><p>The site has no analytics, account system, advertising code or application backend. When hosted online, the hosting provider receives ordinary requests to load the page and may retain server logs. Following an external reference visits that site under its own policies.</p><h2>Control your collection</h2><p>Remove individual bookmarks from their cards. Use the control below to clear this atlas’s saved collection. Other browser data is unaffected.</p><button class="button" data-action="clear-saved">Clear my saved materials</button><h2>Sharing</h2><p>Share copies the current URL to your clipboard when browser permissions allow. For a local file, the site offers the route fragment without copying your local file path. Download controls create files locally.</p></div>`;}
function notFound(message='That page is not part of the atlas.'){title('Page not found');$('#main').innerHTML=`<div class="page">${empty('A thread we couldn’t follow.',esc(message))}<p style="text-align:center;margin-top:25px"><a class="text-link" href="#/atlas/wool">Return to the atlas ${icon('arrow')}</a></p></div>`;}
function render(focus=true){globe?.destroy();globe=null;const r=route();shell(r);const map={atlas:()=>atlas(r.id||'wool',r),materials:()=>library(r),brands:()=>library(r,true),saved:()=>library(r,false,true),fiber:()=>profile(r.id,r.tab),compare:()=>comparePage(r),journeys:()=>routesPage(r),journey:()=>journeyPage(r.id),regions:regionsPage,region:()=>regionPage(r.id),learn:learnPage,article:()=>articlePage(r.id),science:sciencePage,history:()=>historyPage(r),glossary:()=>glossaryPage(r),sources:sourcesPage,about:aboutPage,privacy:privacyPage};try{(map[r.page]||(()=>notFound()))();}catch(error){console.error(error);notFound('This page could not be loaded. Return to the material library to continue.');}if(focus){window.scrollTo(0,0);$('#main').focus({preventScroll:true});}}
function downloadFile(name,data,type='application/json'){const blob=new Blob([data],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Download prepared.');}
async function share(){const value=location.protocol==='file:'?location.hash||'#/atlas/wool':location.href;if(location.protocol==='file:'){showShareFallback(value,'Share this route after opening the atlas. Your local file path is not included.');return;}try{await navigator.clipboard.writeText(value);toast('Link copied.');}catch{showShareFallback(value,'Copy this link to share the current view.');}}
function showShareFallback(value,label){const dialog=$('#search-dialog');dialog.innerHTML=`<div class="dialog-head"><h2 id="search-title">Share this view</h2><button class="icon-btn" data-action="close-dialog" aria-label="Close share dialog">${icon('close')}</button></div><p>${label}</p><label>Link<input class="share-fallback" readonly value="${esc(value)}"></label>`;dialog.showModal();$('input',dialog).select();}
function openSearch(){const dialog=$('#search-dialog');dialog.innerHTML=`<div class="dialog-head"><h2 id="search-title">Follow your curiosity.</h2><button class="icon-btn" data-action="close-dialog" aria-label="Close search">${icon('close')}</button></div><label class="search-field">${icon('search')}<input id="global-search" type="search" placeholder="A fiber, a molecule, a law, a place…" aria-label="Search all materials, glossary terms, journeys and field notes" aria-controls="global-results"></label><div id="global-results" class="search-results" aria-live="polite"></div><small class="muted">Ranked, typo-tolerant search. Try <code>"regenerated cellulose"</code>, <code>silk -muga</code> or <code>law:cites</code>. Arrow keys move between results; Escape closes search.</small>`;
 function draw(){const q=$('#global-search').value;if(!q.trim()){$('#global-results').innerHTML='';return;}
  const ms=searchMaterials(q).slice(0,8),ts=searchTerms({q}).slice(0,5);
  const as=articles.filter(a=>normalize([a.title,a.dek,a.tag,...a.sections.flat()].join(' ')).includes(normalize(q))).slice(0,3);
  const js=journeys.filter(j=>normalize([j.title,...j.countries,byId[j.fiber].name,...j.stops.map(x=>x.name)].join(' ')).includes(normalize(q))).slice(0,4);
  const row=(link,title,meta,extra='')=>`<a class="search-result" href="${link}"><strong>${esc(title)}</strong><small>${meta}</small>${extra}</a>`;
  const html=[...ts.map(({term:t,matched})=>{const key=['definition','explanation','deeper','origins','example','caution'].find(k=>matched[k]);return row('#/glossary/'+t.id,t.term,'Glossary · '+esc(t.category),key?`<span class="match-snippet">${snippet(t[key],matched[key],120)}</span>`:'');}),...ms.map(({material:m,matched})=>row('#/fiber/'+m.id,m.name,'Material · '+esc(m.family),whyMatched(m,matched).replace(/^<p/,'<span').replace(/<\/p>$/,'</span>'))),...as.map(a=>row('#/article/'+a.id,a.title,'Field note')),...js.map(j=>row('#/journey/'+j.id,j.title,'Journey · '+esc(byId[j.fiber].name)))].join('');
  const hint=html?null:(suggestMaterials(q)||suggestTerms(q));
  $('#global-results').innerHTML=html||`<p>No matches.${hint?` Did you mean <button class="text-link" data-global-suggest="${esc(hint)}">${esc(hint)}</button>?`:' Try a fiber name, a process or a country.'}</p>`;}
 dialog.showModal();const input=$('#global-search');input.addEventListener('input',draw);
 dialog.addEventListener('click',e=>{const b=e.target.closest('[data-global-suggest]');if(b){input.value=b.dataset.globalSuggest;draw();input.focus();}});
 dialog.addEventListener('keydown',e=>{if(!['ArrowDown','ArrowUp'].includes(e.key))return;const items=$$('.search-result',dialog);if(!items.length)return;e.preventDefault();const i=items.indexOf(document.activeElement);const next=e.key==='ArrowDown'?(i+1)%items.length:i<=0?(i===0?-1:items.length-1):i-1;(next<0?input:items[next]).focus();});
 draw();input.focus();}
document.addEventListener('click',e=>{
 const cite=e.target.closest('[data-cite]');if(cite){const c=citation(byId[cite.dataset.id])[cite.dataset.cite];navigator.clipboard?.writeText(c).then(()=>toast('Citation copied.'),()=>showShareFallback(c,'Copy this citation.'))??showShareFallback(c,'Copy this citation.');return;}
 const save=e.target.closest('[data-save]');if(save){toggleSave(save.dataset.save);return;}
 const fiber=e.target.closest('[data-fiber]');if(fiber){location.hash=href('atlas',fiber.dataset.fiber);return;}
 const stop=e.target.closest('[data-stop]');if(stop&&globe){selectNode(globe.n.nodes[stop.dataset.stop],byId[route().id||'wool']);return;}
 const projection=e.target.closest('[data-map]');if(projection&&globe){globe.flat=projection.dataset.map==='flat';globe.render();$$('[data-map]').forEach(b=>b.setAttribute('aria-pressed',b===projection));$$('[data-globe]').forEach(b=>b.disabled=globe.flat);return;}
 const tool=e.target.closest('[data-map-tool="fullscreen"]');if(tool){const panel=tool.closest('.map-panel');if(document.fullscreenElement)document.exitFullscreen?.();else panel?.requestFullscreen?.().catch(()=>toast('Full screen is not available here.'));return;}
 const control=e.target.closest('[data-globe]');if(control&&globe){const key=control.dataset.globe;if(key==='left')globe.rotate(20);if(key==='right')globe.rotate(-20);if(key==='in')globe.scale(.1);if(key==='out')globe.scale(-.1);if(key==='reset')globe.reset();if(key==='spin')globe.toggleSpin();spinState();return;}
 const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}
 const weave=e.target.closest('[data-weave]');if(weave){updateWeave(weave.dataset.weave);return;}
 const dl=e.target.closest('[data-download]');if(dl){const j=journeyById[dl.dataset.download];downloadFile('fibers-of-earth-'+j.id+'.json',JSON.stringify({schemaVersion:1,method:'Illustrative route. Great-circle distance between approximate markers; not verified shipments.',...j},null,2));return;}
 const act=e.target.closest('[data-action]')?.dataset.action;
 if(act==='search')openSearch();if(act==='print')print();if(act==='display')openDisplay();if(act==='reset-display'){display={...displayDefaults};try{localStorage.removeItem(DISPLAY_KEY);}catch{}applyDisplay();$('#search-dialog').close();toast('Display settings restored.');if(route().page==='atlas')render(false);}if(act==='close-dialog')$('#search-dialog').close();if(act==='share')share();if(act==='close-node')$('#node-detail').innerHTML='';
 if(act==='expand-glossary'){const ds=$$('#glossary-results details');const open=ds.some(d=>!d.open);ds.forEach(d=>d.open=open);e.target.closest('button').textContent=open?'Collapse all':'Expand all';}
 if(act==='clear-saved'){saved=[];try{localStorage.removeItem('fibersOfEarth.saved.v2');}catch{}toast('Your saved collection is cleared.');}
 if(act==='export-data')downloadFile('fibers-of-earth-atlas.json',JSON.stringify({schemaVersion:3,edition:'2.2.0',methodology:'Educational illustrative routes. No verified shipments. Historical and technical context, not product certification. Detail figures are approximate and condition-dependent.',materials,journeys,sources,glossary:glossaryEntries},null,2));
 if(e.target.closest('#search-dialog a[href^="#/"]'))$('#search-dialog').close();
});
document.addEventListener('keydown',e=>{const tag=document.activeElement?.tagName;if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(tag)&&!$('#search-dialog').open){e.preventDefault();openSearch();}});
window.addEventListener('hashchange',()=>render());
document.addEventListener('fullscreenchange',()=>{const b=$('[data-map-tool="fullscreen"]');if(b){const on=!!document.fullscreenElement;b.setAttribute('aria-pressed',String(on));b.setAttribute('aria-label',on?'Exit full screen':'Show map full screen');}globe?.render();});
render(false);
